type Subject struct {
    mu   sync.RWMutex
    subs []func(Event)
}
func (s *Subject) Subscribe(fn func(Event)) func() {
    s.mu.Lock(); i := len(s.subs); s.subs = append(s.subs, fn); s.mu.Unlock()
    return func() { s.mu.Lock(); s.subs[i] = nil; s.mu.Unlock() }   // tombstone
}
func (s *Subject) Notify(e Event) {
    s.mu.RLock(); fns := append([]func(Event)(nil), s.subs...); s.mu.RUnlock()
    for _, fn := range fns { if fn != nil { fn(e) } }   // no lock held here
}

