type Subject struct { mu sync.Mutex; subs []chan Event }
func (s *Subject) Subscribe(buf int) (<-chan Event, func()) {
    ch := make(chan Event, buf)
    s.mu.Lock(); s.subs = append(s.subs, ch); s.mu.Unlock()
    return ch, func() { /* remove ch under lock, then close(ch) */ }
}
func (s *Subject) Notify(e Event) {
    s.mu.Lock(); subs := append([]chan Event(nil), s.subs...); s.mu.Unlock()
    for _, ch := range subs {
        select { case ch <- e: default: }   // drop on a full channel
    }
}
